/bin/bash -lc "sed -n '1,200p' inputs/restore_request.json && python - <<'PY'
import os, tarfile, zipfile
for p in sorted(os.listdir('inputs')):
    q=os.path.join('inputs',p)
    if tarfile.is_tarfile(q):
        print('\\n',p,'TAR')
        with tarfile.open(q,'r:*') as f:
            for x in f:
                print(repr(x.name), x.type, x.isfile(), x.mtime, x.size)
    elif zipfile.is_zipfile(q):
        print('\\n',p,'ZIP')
        with zipfile.ZipFile(q) as f:
            for x in f.infolist():
                print(repr(x.filename), x.is_dir(), x.date_time, x.file_size, oct(x.external_attr >> 16))
PY"

